// ── Intent Detection ─────────────────────────────────────────────────────
// Input:  { body: { message: "..." } }
// Output: { message: string, intent: string }

const msg = ($input.first().json.body?.message || '').toLowerCase().trim();

const INTENTS = [
  {
    intent: 'COLLAB_ACTIFS',
    keywords: ['actif', 'actifs', 'collaborateur', 'collaborateurs', 'effectif', 'combien']
  },
  {
    intent: 'FORMATIONS_EN_COURS',
    keywords: ['formation', 'formations', 'cours', 'en cours', 'suivi', 'inscrit', 'inscrits']
  },
  {
    intent: 'REPARTITION_DEPT',
    keywords: ['departement', 'département', 'repartition', 'répartition', 'service', 'equipe']
  },
  {
    intent: 'COMPETENCES',
    keywords: ['competence', 'compétence', 'competences', 'compétences', 'skill', 'niveau', 'top']
  },
  {
    intent: 'TAUX_COMPLETION',
    keywords: ['taux', 'completion', 'complétion', 'terminé', 'terminee', 'acheve', 'achevé', 'fini']
  }
];

let detectedIntent = 'UNKNOWN';
for (const { intent, keywords } of INTENTS) {
  if (keywords.some(kw => msg.includes(kw))) {
    detectedIntent = intent;
    break;
  }
}

return [{ json: { message: msg, intent: detectedIntent } }];

// ── Format Reply ─────────────────────────────────────────────────────────
// Reads intent from 'Detect Intent' node, stats from 'Get RH Stats' node.

const intent = $('Detect Intent').first().json.intent;
const s      = $input.first().json; // stats payload

let reply = '';

switch (intent) {

  case 'COLLAB_ACTIFS':
    reply = `👥 Il y a actuellement **${s.collaborateursActifs}** collaborateurs actifs dans le SIRH EY.`;
    break;

  case 'FORMATIONS_EN_COURS':
    reply = `📚 **${s.formationsEnCours}** formation(s) sont actuellement en cours sur un total de **${s.totalInscriptions}** inscription(s).`;
    break;

  case 'REPARTITION_DEPT': {
    const lines = (s.repartitionDept || [])
      .slice(0, 5)
      .map(d => `  • ${d.departement} : ${d.total} collaborateur(s)`)
      .join('\n');
    reply = `🏢 Répartition par département :\n${lines || 'Aucune donnée.'}`;
    break;
  }

  case 'COMPETENCES': {
    const lines = (s.topCompetences || [])
      .map(c => `  • ${c.nom} — ${c.nbCollaborateurs} collab. (niveau moy. ${c.niveauMoyen}/5)`)
      .join('\n');
    reply = `🎯 Top compétences :\n${lines || 'Aucune compétence enregistrée.'}`;
    break;
  }

  case 'TAUX_COMPLETION':
    reply = `✅ Taux de complétion des formations : **${s.tauxCompletion}%** (${s.terminees} terminée(s) sur ${s.totalInscriptions} inscription(s)).`;
    break;

  default:
    reply = `Je peux vous renseigner sur :\n• Les collaborateurs actifs\n• Les formations en cours\n• La répartition par département\n• Les compétences\n• Le taux de complétion\n\nPosez votre question !`;
    break;
}

return [{ json: { reply } }];
